                    Name = e.Name,
                    Value = e.Value is null ? throw MissingRequiredField("value") : ProtoValueConverter.ToJsonElement(e.Value),
                };
                ApplyBaseEvent(result, e.BaseEvent, Proto.EventType.Custom);
