                    RunId = e.RunId,
                    ProtocolVersion = e.HasProtocolVersion ? e.ProtocolVersion : null,
                    ParentRunId = e.HasParentRunId ? e.ParentRunId : null,
                    Input = e.Input is null ? null : ProtoMessageMapper.FromProtoRunAgentInput(e.Input),
                };
                ApplyBaseEvent(result, e.BaseEvent, Proto.EventType.RunStarted);
                return result;
            }
            case Proto.Event.EventOneofCase.RunFinished:
            {
                var e = proto.RunFinished;
                var result = new RunFinishedEvent
                {
                    ThreadId = e.ThreadId,
                    RunId = e.RunId,
                    Result = ProtoValueConverter.ToJsonElementOrNull(e.Result),
                    Usage = BuildUsage(e.Usage),
                };
                result.Outcome = BuildOutcome(e);
                ApplyBaseEvent(result, e.BaseEvent, Proto.EventType.RunFinished);
                return result;
            }
            case Proto.Event.EventOneofCase.RunError:
            {
                var e = proto.RunError;
                var result = new RunErrorEvent
                {
                    Message = e.Message,
                    Code = e.HasCode ? e.Code : null,
